def mask (A : Set DyadicTreeNode) (hA : JamesTreeMaskClosed S A) :
    JamesTreePreSpace 𝕜 p S →L[𝕜] JamesTreePreSpace 𝕜 p S :=
  (maskLinear A).mkContinuous 1 (fun a => by simpa using maskLinear_norm_le A hA a)

